  const [openFaq, setOpenFaq] = useState<number|null>(null)

  useEffect(() => {
    setLang(getStoredLang())
    const h = (e: any) => setLang(e.detail)
    window.addEventListener('langchange', h)
    return () => window.removeEventListener('langchange', h)
  }, [])

  useEffect(() => {
    function easeOut(t: number) { return 1 - Math.pow(1 - t, 3) }
    function animateNum(
      el: HTMLElement, bar: HTMLElement | null,
      target: number, suffix: string, decimals: number, prefix: string, delay: number
    ) {
      const duration = 1600
      let start: number | null = null
      setTimeout(() => {
        if (bar) bar.style.width = '100%'
        function step(ts: number) {
          if (!start) start = ts
          const progress = Math.min((ts - start) / duration, 1)
          const val = target * easeOut(progress)
          const fmt = decimals > 0 ? val.toFixed(decimals) : String(Math.round(val))
          el.textContent = prefix + fmt + suffix
          if (progress < 1) requestAnimationFrame(step)
        }
        requestAnimationFrame(step)
      }, delay)
    }
    const cards = document.querySelectorAll('[data-stat]')
    cards.forEach((card, i) => {
      const numEl = card.querySelector('.stat-num') as HTMLElement
      const barEl = card.querySelector('.stat-bar') as HTMLElement | null
      const num = parseFloat(card.getAttribute('data-num') || '0')
      const suf = card.getAttribute('data-suf') || ''
      const dec = parseInt(card.getAttribute('data-dec') || '0')
      const pre = card.getAttribute('data-pre') || ''
      if (numEl) animateNum(numEl, barEl, num, suf, dec, pre, i * 200)
    })
  }, [])

  const isRTL = lang === 'ar'
  const dir = isRTL ? 'rtl' : 'ltr'

